style.css:
/* Roblox Dark Theme with Custom Background for Stylish */

@namespace url(http://www.w3.org/1999/xhtml);
@-moz-document domain("roblox.com") {
/* Background with Custom Image */
    body {
        background: url('https://images7.alphacoders.com/944/944085.jpg') no-repeat center center fixed !important;
        background-size: cover !important;
        color: #ffffff !important;
    }

    /* Navigation Bar */
    .navbar, .nav-menu, .topbar {
        background-color: rgba(34, 34, 34, 0.8) !important;
        border-bottom: 3px solid #ff0000 !important;
    }

    /* Sidebar */
    .side-menu, .profile-nav {
        background-color: rgba(26, 26, 26, 0.8) !important;
        border-right: 2px solid #ff0000 !important;
    }

    /* Buttons */
    button, .btn-primary, .btn-secondary {
        background-color: #ff0000 !important;
        color: #ffffff !important;
        border: 2px solid #990000 !important;
        padding: 10px 15px !important;
        border-radius: 5px !important;
        font-weight: bold !important;
    }

    button:hover, .btn-primary:hover, .btn-secondary:hover {
        background-color: #cc0000 !important;
        border-color: #660000 !important;
    }

    /* Links */
    a {
        color: #ff3333 !important;
        text-decoration: none !important;
    }

    a:hover {
        color: #ff5555 !important;
        text-decoration: underline !important;
    }

    /* Input Fields */
    input, textarea {
        background-color: #333333 !important;
        color: #ffffff !important;
        border: 1px solid #ff0000 !important;
        padding: 5px !important;
        border-radius: 3px !important;
    }

    input:focus, textarea:focus {
        border-color: #ff5555 !important;
        outline: none !important;
    }

    /* Footer */
    footer {
        background-color: rgba(17, 17, 17, 0.8) !important;
        color: #ffffff !important;
        padding: 10px !important;
        text-align: center !important;
    }
}
